                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            if bottom - top >= 2 and right - left >= 2:
                boxes.append((top, bottom, left, right))

    tiles = []
    color_counts = Counter()
    for top, bottom, left, right in boxes:
        inner = [
            grid[y][x]
            for y in range(top + 1, bottom)
            for x in range(left + 1, right)
            if grid[y][x] != 0
        ]
        if not inner:
            continue
        color = Counter(inner).most_common(1)[0][0]
        tiles.append((top + 1, bottom - 1, left + 1, right - 1, color))
