def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]

    frame = counts.most_common(1)[0][0]
    inner_counts = Counter(
        v for row in grid for v in row if v != 0 and v != frame
    )
    if not inner_counts:
        return [row[:] for row in grid]
    background = inner_counts.most_common(1)[0][0]

    out = [row[:] for row in grid]

    # Extend each non-background interior color along its rows and columns,
    # filling only blank cells and leaving the tile frames intact.
    for r in range(h):
        positions = defaultdict(list)
        for c in range(w):
            color = grid[r][c]
            if color not in (0, frame, background):
                positions[color].append(c)
        for color, xs in positions.items():
            for a, b in zip(xs, xs[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

    for c in range(w):
        positions = defaultdict(list)
        for r in range(h):
            color = grid[r][c]
            if color not in (0, frame, background):
                positions[color].append(r)
        for color, ys in positions.items():
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

    return out
